	@ParameterizedTest
	@ValueSource(ints = { 16, 64 })
	void skewedCompositionVisitsEachNativeLeafOnlyLinearly(int leafCount, @TempDir File directory) {
		CapturingStore store = new CapturingStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			seed(store, 1, 1);
			try (LmdbSailStore.DatasetAdmission admission = store.getBackingStore()
					.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null);
					SailDataset explicit = dataset(store, "E");
					SailDataset inferred = dataset(store, "I")) {
				LmdbPhysicalReadComposition explicitComposition = requireComposition(source(store, explicit));
				LmdbPhysicalReadComposition inferredComposition = requireComposition(source(store, inferred));
				AtomicInteger inspections = new AtomicInteger();
				LmdbPhysicalReadComposition result = null;
				List<Boolean> expected = new ArrayList<>();
				for (int index = 0; index < leafCount; index++) {
					boolean isExplicit = index % 2 == 0;
					LmdbPhysicalReadComposition leaf = new CountingComposition(
							isExplicit ? explicitComposition : inferredComposition, inspections);
					result = result == null ? leaf : LmdbPhysicalReadComposition.union(result, leaf).orElseThrow();
					expected.add(isExplicit);
				}
				assertTrue(inspections.get() <= leafCount,
						"composing an authenticated tree must inspect each leaf at most once: leaves=" + leafCount
								+ ", inspections=" + inspections.get());
				var occurrences = result.planeOccurrences();
				assertEquals(expected, occurrences.stream()
						.map(LmdbPhysicalReadComposition.PlaneOccurrence::explicit)
						.toList());
				assertTrue(inspections.get() <= 2 * leafCount,
						"at-use flattening and liveness validation must add only one visit per leaf: leaves="
								+ leafCount
								+ ", inspections=" + inspections.get());
				assertOnePair(occurrences);
			}
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "E", "I" })
	void physicalCostCurrentnessRejectsAnOpenPublicationDespiteActiveDatasetCurrentness(String plane,
			@TempDir File directory) {
		CapturingStore store = new CapturingStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			seed(store, 1, 1);
			try (var admission = store.getBackingStore().beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null);
					SailDataset dataset = dataset(store, plane)) {
				var owner = requireComposition(source(store, dataset)).planeOccurrences().getFirst().owner();
				assertTrue(owner.isCurrentForPhysicalCost(), "a stable current owner qualifies physical metadata");
				try (var publication = store.getBackingStore().beginPublication(new Object())) {
					assertTrue(dataset.isSnapshotCurrent(), "the active reserved owner still serves its own rows");
					assertFalse(owner.isCurrentForPhysicalCost(),
							"an open publication cannot certify correspondence with published synopsis metadata");
					assertEquals(1, statementCount(source(store, dataset)));
				}
				assertTrue(owner.isCurrentForPhysicalCost(), "closing an unchanged publication restores qualification");
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void physicalCostCurrentnessDeclinesOldOwnerWithoutReplacingItsSnapshot(@TempDir File directory) {
		CapturingStore store = new CapturingStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			seed(store, 1, 0);
			try (SailDataset old = dataset(store, "E")) {
				var source = source(store, old);
				var owner = requireComposition(source).planeOccurrences().getFirst().owner();
				assertTrue(owner.isCurrentForPhysicalCost());
				var oldTxn = owner.pinnedReadTxn().orElseThrow();
				var oldDictionary = owner.pinnedValueSnapshot().orElseThrow();
				try (RepositoryConnection writer = repository.getConnection()) {
					writer.add(B, P, VF.createLiteral(2), G);
				}
				assertFalse(owner.isCurrentForPhysicalCost());
				assertSame(oldTxn, owner.pinnedReadTxn().orElseThrow());
				assertSame(oldDictionary, owner.pinnedValueSnapshot().orElseThrow());
				assertEquals(1, statementCount(source), "declining physical metadata does not renew the row snapshot");
				try (SailDataset current = dataset(store, "E")) {
					var currentSource = source(store, current);
					assertTrue(requireComposition(currentSource).planeOccurrences()
							.getFirst()
							.owner()
							.isCurrentForPhysicalCost());
					assertEquals(2, statementCount(currentSource));
				}
			}
		} finally {
			repository.shutDown();
		}
	}

