	private record CountingComposition(LmdbPhysicalReadComposition delegate, AtomicInteger inspections)
			implements LmdbPhysicalReadComposition {
		@Override
		public List<PlaneOccurrence> planeOccurrences() {
			inspections.incrementAndGet();
			return delegate.planeOccurrences();
		}
	}

	@ParameterizedTest
	@ValueSource(strings = { "E", "I", "EI", "IE", "EIE", "EE" })
	void nativeCompositionPreservesOrderedPlaneOccurrences(String shape, @TempDir File directory) {
		CapturingStore store = new CapturingStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			seed(store, 1, 3);
			try (LmdbSailStore.DatasetAdmission admission = store.getBackingStore()
					.beginDatasetAdmission(IsolationLevels.SNAPSHOT_READ, null);
					SailDataset dataset = dataset(store, shape)) {
				SailDatasetTripleTermSource source = source(store, dataset);
				LmdbPhysicalReadComposition composition = requireComposition(source);
				List<Boolean> expected = shape.chars().mapToObj(c -> c == 'E').toList();
				assertEquals(expected, composition.planeOccurrences()
						.stream()
						.map(LmdbPhysicalReadComposition.PlaneOccurrence::explicit)
						.toList());
				for (var occurrence : composition.planeOccurrences()) {
					assertSame(admission.view().tripleTxn(), occurrence.owner().pinnedReadTxn().orElseThrow());
					assertSame(admission.view().valueSnapshot(),
							occurrence.owner().pinnedValueSnapshot().orElseThrow());
				}
				assertEquals(expected.stream().mapToInt(explicit -> explicit ? 1 : 3).sum(), statementCount(source),
						"duplicate plane occurrences preserve physical statement bag multiplicity");
			}
		} finally {
			repository.shutDown();
		}
	}

