	@Test
	void retiredButBorrowedSnapshotKeepsItsOwnPairAfterReplacementCommit(@TempDir File directory) {
		CapturingStore store = new CapturingStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			seed(store, 1, 0);
			List<Long> observed = new ArrayList<>();
			store.observer = actual -> {
				var occurrences = requireComposition(actual).planeOccurrences();
				assertOnePair(occurrences);
				observed.add(occurrences.getFirst().owner().pinnedReadTxn().orElseThrow().nativeTransactionId());
			};
			try (RepositoryConnection reader = repository.getConnection();
					RepositoryConnection writer = repository.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT);
				assertEquals(1, rows(reader, false));
				writer.add(B, P, VF.createLiteral(2), G);
				assertEquals(1, rows(reader, false), "the borrowed snapshot keeps its original query bag");
				assertEquals(observed.get(0), observed.get(1), "the retained query must keep the exact old pair");
				reader.commit();
				assertEquals(2, rows(reader, false));
				assertNotEquals(observed.getFirst(), observed.getLast(), "replacement queries receive a new pair");
			}
		} finally {
			repository.shutDown();
		}
	}

