	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void differentPairOrForeignUnionDeclinesCompleteComposition(boolean foreign, @TempDir File directory) {
		CapturingStore firstStore = new CapturingStore(new File(directory, "first"));
		CapturingStore secondStore = new CapturingStore(new File(directory, "second"));
		SailRepository firstRepository = new SailRepository(firstStore);
		SailRepository secondRepository = new SailRepository(secondStore);
		firstRepository.init();
		secondRepository.init();
		try {
			seed(firstStore, 1, 0);
			seed(secondStore, 1, 0);
			try (SailDataset first = dataset(firstStore, "E")) {
				if (!foreign) {
					try (RepositoryConnection writer = firstRepository.getConnection()) {
						writer.add(B, P, VF.createLiteral(2), G);
					}
				}
				try (SailDataset second = dataset(foreign ? secondStore : firstStore, "E");
						SailDataset combined = union(first, second)) {
					LmdbPinnedReadTxnSource firstOwner = first.unwrap(LmdbPinnedReadTxnSource.class).orElseThrow();
					LmdbPinnedReadTxnSource secondOwner = second.unwrap(LmdbPinnedReadTxnSource.class).orElseThrow();
					assertNotSame(firstOwner.pinnedReadTxn().orElseThrow(), secondOwner.pinnedReadTxn().orElseThrow());
					assertNotSame(firstOwner.pinnedValueSnapshot().orElseThrow(),
							secondOwner.pinnedValueSnapshot().orElseThrow());
					assertTrue(resolve(source(firstStore, combined)).isEmpty());
					assertEquals(foreign ? 2 : 3, statementCount(source(firstStore, combined)));
				}
			}
		} finally {
			try {
				secondRepository.shutDown();
			} finally {
				firstRepository.shutDown();
			}
		}
	}

